        for position, line in enumerate(entry_lines):
            try:
                text = line.decode("utf-8")
            except UnicodeDecodeError as error:
                raise CorruptionError("entry line is not valid UTF-8", path=path, line=position + 2) from error
            tab = text.find("\t")
            if tab <= 0:
                raise CorruptionError("entry without a key separator", path=path, line=position + 2)
            key = text[:tab]
            if previous_key is not None and key <= previous_key:
                raise CorruptionError(
                    "entries must be strictly ascending and unique",
                    path=path,
                    line=position + 2,
                    key=key,
                )
            _decode_value(text[tab + 1 :])  # every value column is validated now
            if position % BLOCK_ENTRIES == 0:
                blocks.append(_BlockRef(first_key=key, start=offset, end=-1))
            if min_key is None:
                min_key = key
            max_key = key
            previous_key = key
            offset += len(line) + 1  # LF stripped by splitlines
        for index, block in enumerate(blocks):
            block.end = blocks[index + 1].start if index + 1 < len(blocks) else len(prefix)

        return cls(path=path, bloom=bloom, count=count, size=len(raw), blocks=blocks, min_key=min_key, max_key=max_key)

    # -- reads ---------------------------------------------------------------
    def __len__(self) -> int:
        return self.count

    def get(self, key: str) -> tuple[bool, str | None]:
        """Return `(found, value)`; a tombstone is found with value None.

        A bloom rejection touches no entry bytes at all. A possible hit reads just the one block
        whose first-key range brackets `key` -- bounded data, independent of table size.
        """
        if self.count == 0 or not self.bloom.might_contain(key):
            return False, None
        if key < self._min_key or key > self._max_key:
            return False, None
        block = self._block_for(key)
        if block is None:
            return False, None
        found, value = self._read_block(block, key)
        if found:
            return True, value
        # Bloom false positives are normal; they must look exactly like a miss, never corruption.
        return False, None

    def scan(
        self,
        start: str | None = None,
        end: str | None = None,
        limit: int | None = None,
    ) -> Iterator[tuple[str, str | None]]:
        """Yield `(key, value)` pairs in order, reading blocks lazily; None values are tombstones."""
        if self.count == 0:
            return
        if start is not None and self._max_key < start:
            return
        if end is not None and self._min_key >= end:
            return
        produced = 0
        for block in self._blocks_from(start):
            for key, value in self._iter_block(block):
                if start is not None and key < start:
                    continue
                if end is not None and key >= end:
                    return
                yield key, value
                produced += 1
                if limit is not None and produced >= limit:
                    return

    def items(self) -> list[tuple[str, str | None]]:
        """Materialize the whole table -- retained for small-table callers and tests only."""
        return list(self.scan())

    def to_document(self) -> dict[str, object]:
        return {"path": self.path, "keys": self.count, "bloom": self.bloom.to_document()}

    # -- internals -----------------------------------------------------------
    def _block_for(self, key: str) -> _BlockRef | None:
        import bisect

        first_keys = [block.first_key for block in self._blocks]
        index = bisect.bisect_right(first_keys, key) - 1
        if index < 0:
            return None
        return self._blocks[index]

    def _blocks_from(self, start: str | None) -> Iterator[_BlockRef]:
        import bisect

        if start is None:
            yield from self._blocks
            return
        first_keys = [block.first_key for block in self._blocks]
        yield from self._blocks[bisect.bisect_right(first_keys, start) - 1 :] if first_keys and start <= self._max_key else iter(())

    def _read_block(self, block: _BlockRef, key: str) -> tuple[bool, str | None]:
        import bisect

        with open(self.path, "rb") as handle:
            handle.seek(block.start)
            chunk = handle.read(block.end - block.start)
        rows = self._parse_block(chunk, block.start)
        keys = [candidate for candidate, _ in rows]
        index = bisect.bisect_left(keys, key)
        if index < len(keys) and keys[index] == key:
            return True, rows[index][1]
        return False, None

    def _iter_block(self, block: _BlockRef) -> Iterator[tuple[str, str | None]]:
        with open(self.path, "rb") as handle:
            handle.seek(block.start)
            chunk = handle.read(block.end - block.start)
        yield from self._parse_block(chunk, block.start)

    def _parse_block(self, chunk: bytes, start_offset: int) -> list[tuple[str, str | None]]:
        try:
            text = chunk.decode("utf-8")
        except UnicodeDecodeError as error:
            raise CorruptionError("entry block is not valid UTF-8", path=self.path) from error
        rows: list[tuple[str, str | None]] = []
        for line in text.splitlines():
            key, separator, encoded = line.partition("\t")
            if not separator:
                raise CorruptionError("entry without a key separator", path=self.path)
            rows.append((key, _decode_value(encoded)))
        if not rows:
            raise CorruptionError("indexed block holds no entries", path=self.path, offset=start_offset)
        return rows

